import logEachMap = require( './index' );

/**
* Callback function.
*
* @param x - first value
* @param y - second value
* @returns sum
*/
function sum( x: number, y: number ): number {
	return x + y;
}

// TESTS //

// The function returns void...
{
	const x = [ 1, 2, 3 ];
	const y = [ 4, 5, 6 ];

	logEachMap( '%d + %d = %d', x, y, sum ); // $ExpectType void
}

// The compiler throws an error if the first argument is not a string...
{
	const x = [ 1, 2, 3 ];
	const y = [ 4, 5, 6 ];

	logEachMap( 123, x, y, sum ); // $ExpectError
	logEachMap( true, x, y, sum ); // $ExpectError
	logEachMap( false, x, y, sum ); // $ExpectError
	logEachMap( null, x, y, sum ); // $ExpectError
	logEachMap( undefined, x, y, sum ); // $ExpectError
	logEachMap( [], x, y, sum ); // $ExpectError
	logEachMap( {}, x, y, sum ); // $ExpectError
}
